// Decide what to do with one GitHub webhook event.
// route 0 = new issue: add to board + triage agent
// route 1 = repository_dispatch to GitHub Actions
// route 2 = Discord message
const raw = $input.first().json;
const e = raw.body ?? raw;
const out = [];
const dispatch = (event_type, client_payload) => ({ event_type, client_payload });

// New issue (not a PR)
if (e.action === 'opened' && e.issue && !e.issue.pull_request) {
  out.push({ route: 0,
    graphql: { query: 'mutation($p:ID!,$c:ID!){addProjectV2ItemById(input:{projectId:$p,contentId:$c}){item{id}}}',
               variables: { p: '__PROJECT_ID__', c: e.issue.node_id } },
    dispatch: dispatch('agent-triage', { issue: e.issue.number }) });
}

// A human adds "agent:ready". Only users with triage rights can add labels.
// Bots (e.g. the triage agent) are ignored, so issue text cannot start the work agent.
if (e.action === 'labeled' && e.issue && e.label?.name === 'agent:ready' && e.sender?.type === 'User') {
  out.push({ route: 1, dispatch: dispatch('agent-work', { issue: e.issue.number }) });
}

// Agent is blocked
if (e.action === 'labeled' && e.issue && e.label?.name === 'needs-human') {
  out.push({ route: 2, message: `🙋 Needs a human: #${e.issue.number} ${e.issue.title}\n${e.issue.html_url}` });
}

// Milestone "v1.2.3 – Title" closed → release
if (e.action === 'closed' && e.milestone && !e.issue && !e.pull_request) {
  const m = /v?(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)/.exec(e.milestone.title);
  if (m) {
    out.push({ route: 1, dispatch: dispatch('release', { version: m[1] }) });
    out.push({ route: 2, message: `🚀 Release v${m[1]} started (milestone "${e.milestone.title}" closed).` });
  } else {
    out.push({ route: 2, message: `⚠️ Milestone "${e.milestone.title}" closed, but it has no version like v1.2.3. No release.` });
  }
}

// Release published
if (e.action === 'published' && e.release) {
  out.push({ route: 2, message: `🎉 ${e.release.name || e.release.tag_name} is out!\n${e.release.html_url}` });
}

// PR merged
if (e.action === 'closed' && e.pull_request?.merged) {
  out.push({ route: 2, message: `✅ Merged #${e.pull_request.number}: ${e.pull_request.title}` });
}

// Failed workflow run on main (agents, release) or on an agent branch
if (e.action === 'completed' && e.workflow_run && e.workflow_run.conclusion === 'failure') {
  const r = e.workflow_run;
  if (r.head_branch === 'main' || r.head_branch?.startsWith('agent/')) {
    out.push({ route: 2, message: `❌ ${r.name} failed on ${r.head_branch}\n${r.html_url}` });
  }
}

return out.map(json => ({ json }));
